INSERT INTO `pages` (`id`, `uuid`, `title`, `slug`, `content`, `excerpt`, `featured_image`, `author_id`, `status`, `meta_title`, `meta_description`, `meta_keywords`, `template`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '2f8decf7-963a-46a6-b422-9b7f466d0ee1', 'Profil Perusahaan', 'profil', '<h2>Tentang Poros Aktual</h2><p>Poros Aktual adalah portal berita online yang menyajikan informasi terkini, akurat, dan terpercaya. Kami berkomitmen untuk memberikan liputan berita yang berimbang dan objektif.</p><p>Didirikan pada tahun 2024, Poros Aktual hadir sebagai sumber informasi terpercaya bagi masyarakat Indonesia.</p>', NULL, NULL, 1, 'published', NULL, NULL, NULL, 'default', '2026-08-28 09:30:57', '2026-08-28 09:30:57', NULL),
(2, '9207449c-fa8e-4084-8c61-c905bb9da2cf', 'Visi & Misi', 'visi-misi', '<h2>Visi</h2><p>Menjadi portal berita online terdepan dan terpercaya di Indonesia.</p><h2>Misi</h2><ul><li>Menyajikan berita yang akurat dan berimbang</li><li>Memberikan informasi yang bermanfaat bagi masyarakat</li><li>Menjaga kredibilitas dan integritas jurnalistik</li><li>Memanfaatkan teknologi untuk penyebaran informasi yang lebih baik</li></ul>', NULL, NULL, 1, 'published', NULL, NULL, NULL, 'default', '2026-08-28 09:30:57', '2026-08-28 09:30:57', NULL),
(3, 'fea5cf33-83fa-4e51-963a-e103cfeb9178', 'Pedoman Media Siber', 'pedoman-siber', '<h2>Pedoman Media Siber</h2><p>Poros Aktual berpedoman pada Pedoman Media Siber yang ditetapkan oleh Dewan Pers. Berikut adalah prinsip-prinsip yang kami junjung tinggi:</p><ul><li>Akurasi dan kebenaran informasi</li><li>Independensi jurnalistik</li><li>Tanggung jawab sosial</li><li>Perlindungan narasumber</li><li>Hak jawab dan hak koreksi</li></ul>', NULL, NULL, 1, 'published', NULL, NULL, NULL, 'default', '2026-08-28 09:30:57', '2026-08-28 09:30:57', NULL),
(4, 'd0c1eec3-e7a3-4467-96b1-70d25e380d3d', 'Redaksi', 'redaksi', '<h2>Tim Redaksi Poros Aktual</h2><p>Redaksi Poros Aktual terdiri dari jurnalis profesional yang berpengalaman di bidangnya masing-masing.</p><h3>Daftar Redaksi</h3><ul><li><strong>Editor in Chief:</strong> Editor Utama</li><li><strong>Wartawan Senior:</strong> Budi Santoso</li></ul>', NULL, NULL, 1, 'published', NULL, NULL, NULL, 'default', '2026-08-28 09:30:57', '2026-08-28 09:30:57', NULL),
(5, 'ed78ce3f-d5f6-44e2-a514-71b730c328dd', 'Disclaimer', 'disclaimer', '<h2>Disclaimer</h2><p>Seluruh konten yang diterbitkan di Poros Aktual adalah untuk tujuan informasi. Kami tidak bertanggung jawab atas keputusan yang diambil berdasarkan informasi dari situs ini.</p><p>Informasi yang tersedia di situs ini dapat berubah sewaktu-waktu tanpa pemberitahuan terlebih dahulu.</p>', NULL, NULL, 1, 'published', NULL, NULL, NULL, 'default', '2026-08-28 09:30:57', '2026-08-28 09:30:57', NULL),
(6, '9905f980-6871-4358-874e-58a0ba5522b2', 'Privacy Policy', 'privacy-policy', '<h2>Kebijakan Privasi</h2><p>Kami menghargai privasi pengunjung situs kami. Kebijakan privasi ini menjelaskan bagaimana kami mengumpulkan dan menggunakan data pengunjung.</p><h3>Pengumpulan Data</h3><p>Kami mengumpulkan data seperti alamat IP, jenis browser, dan halaman yang dikunjungi untuk keperluan analisis.</p><h3>Penggunaan Data</h3><p>Data yang dikumpulkan digunakan untuk meningkatkan kualitas layanan dan pengalaman pengunjung.</p>', NULL, NULL, 1, 'published', NULL, NULL, NULL, 'default', '2026-08-28 09:30:57', '2026-08-28 09:30:57', NULL),
(7, '954721d7-17e9-4fa5-bed4-ec7ad7208bf1', 'Hubungi Kami', 'kontak', '<h2>Hubungi Kami</h2><p>Redaksi Poros Aktual</p><ul><li>Email: info@porosaktual.com</li><li>Telepon: +62 21 1234 5678</li><li>Alamat: Jl. Teknologi No. 1, Jakarta Selatan, Indonesia</li></ul><h2>Beriklan</h2><p>Tertarik beriklan di Poros Aktual? Hubungi tim marketing kami:</p><ul><li>Email: iklan@porosaktual.com</li><li>Telepon: +62 21 1234 5679</li></ul>', NULL, NULL, 1, 'published', NULL, NULL, NULL, 'default', '2026-08-28 09:30:57', '2026-08-28 09:30:57', NULL);

